<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import type {RequestFn} from './media';import {buyKey} from './lib';
type Row=Record<string,any>;const props=defineProps<{request:RequestFn,editable?:boolean}>();
const platform=ref('Android'),platforms=['Android','iOS','Windows','macOS','Linux'],document=ref<Row>({title:'客户端教程',intro:'',apps:[],faqs:[]}),version=ref(0),draft=ref<Row|null>(null),busy=ref(false),error=ref(''),notice=ref('');
const available=computed(()=>document.value.apps.filter((a:Row)=>a.platforms.includes(platform.value)));
async function load(){busy.value=true;error.value='';try{const d=await props.request('client-help');document.value=d.document;version.value=d.version}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
function edit(){draft.value=JSON.parse(JSON.stringify(document.value));for(const a of draft.value!.apps)a.steps_text=a.steps.join('\n');error.value='';notice.value=''}
async function save(){if(!draft.value)return;busy.value=true;error.value='';try{const d=JSON.parse(JSON.stringify(draft.value));d.apps=d.apps.map(({steps_text,...a}:Row)=>({...a,steps:steps_text.split('\n').map((x:string)=>x.trim()).filter(Boolean)}));await props.request('admin/client-help','PUT',{version:version.value,document:d});draft.value=null;await load();notice.value='教程已保存，用户下次打开教程时即可读取'}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
function addClient(){draft.value?.apps.push({id:buyKey(),name:'',format:'',url:'',platforms:['Android'],steps_text:''})}
onMounted(load);
</script>
<template><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div><section class="panel"><div class="section-head"><h2>{{document.title}}</h2><div class="actions"><button :disabled="busy" @click="load">刷新教程</button><button v-if="editable" class="primary" :disabled="busy" @click="edit">编辑教程</button></div></div><p class="pre">{{document.intro}}</p><div class="actions" role="tablist" aria-label="操作系统"><button v-for="p in platforms" :key="p" :class="{primary:p===platform}" role="tab" :aria-selected="p===platform" @click="platform=p">{{p}}</button></div></section><div class="help-grid"><section class="panel" v-for="a in available" :key="a.id"><h3>{{a.name}}</h3><p class="muted">建议格式：{{a.format}}</p><ol><li v-for="(step,i) in a.steps" :key="i">{{step}}</li></ol><a v-if="a.url" :href="a.url" target="_blank" rel="noopener noreferrer">项目 / 使用说明 ↗</a></section></div><section class="panel" v-if="document.faqs.length"><h3>常见问题</h3><details v-for="(f,i) in document.faqs" :key="i"><summary>{{f.question}}</summary><p class="pre">{{f.answer}}</p></details></section>
<div v-if="draft" class="modal-backdrop"><form class="modal help-editor" role="dialog" aria-label="编辑客户端教程" aria-modal="true" @submit.prevent="save"><div class="section-head"><h2>编辑客户端教程</h2><button type="button" :disabled="busy" @click="draft=null" aria-label="关闭">×</button></div><p v-if="error" class="alert error">{{error}}</p><label>教程标题<input v-model="draft.title" required maxlength="100"></label><label>导入说明<textarea v-model="draft.intro" rows="3" maxlength="2000"/></label><h3>客户端条目</h3><p class="muted">显示顺序按条目顺序。每行一个导入步骤，链接只允许 HTTPS；保存后对所有用户生效。</p><article class="help-edit-card" v-for="(a,i) in draft.apps" :key="a.id"><div class="fields"><label>客户端名称<input v-model="a.name" maxlength="80" required></label><label>建议订阅格式<input v-model="a.format" maxlength="120"></label><label class="wide">项目 / 教程链接<input v-model="a.url" type="url" placeholder="https://" maxlength="1000"></label></div><div class="flags"><label v-for="p in platforms" :key="p" class="multi"><input type="checkbox" v-model="a.platforms" :value="p">{{p}}</label></div><label>导入步骤 · 每行一条<textarea v-model="a.steps_text" rows="4" required/></label><div class="actions"><button type="button" :disabled="i===0" @click="draft.apps.splice(Number(i)-1,0,draft.apps.splice(i,1)[0])">上移</button><button type="button" :disabled="i===draft.apps.length-1" @click="draft.apps.splice(Number(i)+1,0,draft.apps.splice(i,1)[0])">下移</button><button type="button" @click="draft.apps.splice(i,1)">移除此客户端</button></div></article><button type="button" :disabled="draft.apps.length>=30" @click="addClient">＋ 添加客户端</button><h3>常见问题</h3><article v-for="(f,i) in draft.faqs" :key="i" class="help-edit-card"><label>问题<input v-model="f.question" maxlength="180" required></label><label>解答<textarea v-model="f.answer" maxlength="3000" required/></label><button type="button" @click="draft.faqs.splice(i,1)">移除此问题</button></article><button type="button" :disabled="draft.faqs.length>=30" @click="draft.faqs.push({question:'',answer:''})">＋ 添加问题</button><div class="modal-actions"><button type="button" :disabled="busy" @click="draft=null">取消</button><button class="primary" :disabled="busy">保存教程</button></div></form></div></template>
<style scoped>.help-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:18px}.help-grid ol{padding-left:20px}.help-grid li{margin:12px 0;line-height:1.8;overflow-wrap:anywhere}.help-grid .panel{margin:0 0 18px}details{padding:14px 0;border-bottom:1px solid #edf0f5}summary{cursor:pointer;font-weight:600;overflow-wrap:anywhere}details p{margin-top:12px}.help-edit-card{padding:20px;border:1px solid #e2e8ef;border-radius:12px;margin:16px 0}.help-editor{width:min(900px,100%)}.help-edit-card .flags{display:flex;gap:16px;flex-wrap:wrap}.help-edit-card .actions{justify-content:flex-end}</style>
